/*!
 * GSAP Compatibility Library (NEXUS VR Engine)
 * Provides safe fallback API for gsap, ScrollTrigger, and animations
 */
(function(window) {
  "use strict";

  const gsap = {
    version: "3.12.5",
    registerPlugin: function() { return true; },
    core: { globals: function() { return {}; } },
    utils: {
      toArray: function(selector) {
        if (!selector) return [];
        if (typeof selector === "string") return Array.from(document.querySelectorAll(selector));
        if (selector.nodeType) return [selector];
        if (Array.isArray(selector) || selector instanceof NodeList) return Array.from(selector);
        return [];
      },
      clamp: function(min, max, val) {
        return Math.min(Math.max(val, min), max);
      }
    },
    set: function(targets, vars) {
      const els = gsap.utils.toArray(targets);
      els.forEach(function(el) {
        if (!el || !el.style) return;
        if (vars.opacity !== undefined) el.style.opacity = vars.opacity;
        if (vars.y !== undefined) el.style.transform = `translateY(${vars.y}px)`;
        if (vars.x !== undefined) el.style.transform = `translateX(${vars.x}px)`;
        if (vars.scale !== undefined) el.style.transform = `scale(${vars.scale})`;
      });
      return gsap;
    },
    to: function(targets, vars) {
      const els = gsap.utils.toArray(targets);
      const duration = (vars.duration || 0.5) * 1000;
      els.forEach(function(el) {
        if (!el || !el.style) return;
        el.style.transition = `all ${duration}ms cubic-bezier(0.16, 1, 0.3, 1)`;
        if (vars.opacity !== undefined) el.style.opacity = vars.opacity;
        if (vars.y !== undefined) el.style.transform = `translateY(${vars.y}px)`;
        if (vars.x !== undefined) el.style.transform = `translateX(${vars.x}px)`;
        if (vars.scale !== undefined) el.style.transform = `scale(${vars.scale})`;
      });
      if (typeof vars.onComplete === "function") {
        setTimeout(vars.onComplete, duration);
      }
      return gsap;
    },
    fromTo: function(targets, fromVars, toVars) {
      gsap.set(targets, fromVars);
      requestAnimationFrame(function() {
        requestAnimationFrame(function() {
          gsap.to(targets, toVars);
        });
      });
      return gsap;
    }
  };

  window.gsap = gsap;
})(window);
